std::vector<RtspPlayer::MgQualitySnapshot> RtspPlayer::getMgRtpQuality() const {
    std::vector<MgQualitySnapshot> result;
    for (size_t i = 0; i < _mg_quality.size(); ++i) {
        const auto &track = _mg_quality[i];
        if (track.seen_ssrc) {
            result.push_back({static_cast<int>(i), track.track_type, track.ssrc,
                              track.sample_rate, track.last_arrival_ms, track.sequence.snapshot()});
        }
    }
    return result;
}

void RtspPlayer::teardown() {
    for (auto &track : _mg_quality) {
        track.sequence.reset();
        track.seen_ssrc = false;
        track.last_arrival_ms = 0;
    }
    sendTeardown();

