api_regist("/index/api/getProxyRtpQuality", [](API_ARGS_MAP_ASYNC) {
    CHECK_SECRET();
    CHECK_ARGS("key");
    std::string key = allArgs["key"];
    auto proxy = s_player_proxy.find(key);
    if (!proxy) {
        throw ApiRetException("can not find the stream proxy", API::NotFound);
    }
    proxy->getPoller()->async([=]() mutable {
        auto rtsp = std::dynamic_pointer_cast<RtspPlayer>(proxy->getDelegate());
        auto &data = val["data"];
        data["key"] = key;
        data["supported"] = static_cast<bool>(rtsp);
        data["scope"] = "application_pre_sort";
        data["metrics_version"] = 1;
        data["tracks"] = Json::Value(Json::arrayValue);
        if (rtsp) {
            data["instance_id"] = Json::UInt64(rtsp->getMgInstanceId());
            data["transport"] = rtsp->getMgTransport();
            data["proxy_status"] = proxy->getStatus();
            const auto now = getCurrentMillisecond();
            for (const auto &track : rtsp->getMgRtpQuality()) {
                const auto &s = track.sequence;
                Json::Value item;
                item["track_index"] = track.track_index;
                item["track_type"] = track.track_type;
                item["ssrc"] = Json::UInt64(track.ssrc);
                item["sample_rate"] = track.sample_rate;
                item["sample_age_ms"] = Json::UInt64(now >= track.last_arrival_ms ? now - track.last_arrival_ms : 0);
                item["epoch"] = Json::UInt64(s.epoch);
                item["received"] = Json::UInt64(s.received);
                item["unique"] = Json::UInt64(s.unique);
                item["reordered"] = Json::UInt64(s.reordered);
                item["duplicates"] = Json::UInt64(s.duplicates);
                item["too_old"] = Json::UInt64(s.too_old);
                item["discontinuities"] = Json::UInt64(s.discontinuities);
                item["highest_extended"] = Json::Int64(s.highest_extended);
                item["window"] = 1024;
                data["tracks"].append(item);
            }
        }
        invoker(200, headerOut, val.toStyledString());
    });
});

